  const getBestMajorStreamFromCounts = (counts) => {
    const order = ['ns', 'ba', 'sd'];
    let best = { key: order[0], count: 0 };
    order.forEach((key) => {
      const count = counts[key] || 0;
      if (count > best.count) best = { key, count };
    });
    return best;
  };
